CREATE OR REPLACE PROCEDURE sp(arg1 real, arg2 text, arg3 real, arg4 text)
LANGUAGE plpgsql
AS $$
DECLARE
    result_val real;
    status_text text := 'pending';
    suffix_text text := '_suffix';
BEGIN
    IF arg1 < 0 THEN
        result_val := arg1 * -1;
        UPDATE chip_model
        SET WiFi = arg2,
            RAM_MiB = result_val
        WHERE WiFi = arg2;
    ELSIF arg1 < 10 THEN
        result_val := arg1 + 5;
        DELETE FROM chip_model
        WHERE RAM_MiB = arg1;
    ELSIF arg1 < 20 THEN
        result_val := arg1 * 2;
        UPDATE screen_mode
        SET used_kb = arg3 + result_val
        WHERE Pixels = arg4;
    ELSIF arg1 < 30 THEN
        result_val := arg1 - 8;
        DELETE FROM screen_mode
        WHERE used_kb = arg3;
    ELSE
        result_val := arg1 / 2;
        status_text := 'processed';
    END IF;

    UPDATE phone
    SET Accreditation_level = Accreditation_level || suffix_text
    WHERE EXISTS (
        SELECT 1
        FROM screen_mode sm
        WHERE sm.Pixels = arg4
          AND sm.used_kb = arg3
          AND phone.screen_mode = sm.Graphics_mode::text
    );

    UPDATE phone
    SET Accreditation_type = Accreditation_type || '_wifi_match'
    WHERE EXISTS (
        SELECT 1
        FROM chip_model cm
        WHERE cm.WiFi = arg2
          AND phone.chip_model = cm.Model_name
    );

    UPDATE phone
    SET Hardware_Model_name = Hardware_Model_name || '_ram_wifi_match'
    WHERE EXISTS (
        SELECT 1
        FROM chip_model cm
        WHERE cm.RAM_MiB = arg1
          AND cm.WiFi = arg2
          AND phone.chip_model = cm.Model_name
    );

    UPDATE phone
    SET Accreditation_type = Accreditation_type || '_dual_match'
    WHERE EXISTS (
        SELECT 1
        FROM chip_model cm
        WHERE cm.WiFi = arg2
          AND cm.Model_name = phone.chip_model
    )
    AND EXISTS (
        SELECT 1
        FROM screen_mode sm
        WHERE sm.Pixels = arg4
          AND phone.screen_mode = sm.Graphics_mode::text
    );

    UPDATE chip_model
    SET WiFi = arg2 || status_text
    WHERE RAM_MiB = arg1;

    result_val := result_val + 3;

    UPDATE screen_mode
    SET Pixels = arg4 || '_updated'
    WHERE used_kb = arg3;

    DELETE FROM chip_model
    WHERE RAM_MiB > result_val;

    status_text := 'active';

    UPDATE screen_mode
    SET used_kb = arg3 + 12
    WHERE Pixels = arg4;

    UPDATE chip_model
    SET RAM_MiB = result_val
    WHERE WiFi = arg2;

    result_val := result_val - 7;

    DELETE FROM screen_mode
    WHERE Pixels = arg4 || '_old';

    UPDATE chip_model
    SET WiFi = arg2 || suffix_text
    WHERE RAM_MiB = arg1;

    status_text := 'completed';

    UPDATE screen_mode
    SET used_kb = arg3 * 3
    WHERE Pixels = arg4;

    DELETE FROM chip_model
    WHERE WiFi = arg2 || status_text;
END;
$$;

